  visitId?: string;
  metadata?: Record<string, unknown>;
};

export function inferSeverityColor(
  status?: string | null,
  flags?: string[] | null,
): SeverityColor {
  const hay = `${status ?? ""} ${(flags ?? []).join(" ")}`.toUpperCase();
  if (/SEVERE|CRITICAL/.test(hay)) return "red";
  if (/WASTING|STUNTING|UNDERWEIGHT|OBESITY|MICROCEPHALY|MACROCEPHALY/.test(hay))
    return "orange";
  if (/OVERWEIGHT|SHORT|TALL|CAUTION|MILD/.test(hay)) return "yellow";
  if (!status || /NORMAL|HEALTHY|ADEQUATE/.test(hay)) return "green";
  return "yellow";
}

export async function parseApiError(res: Response): Promise<string> {
  try {
    const data = (await res.json()) as {
      error?: string;
      details?: { formErrors?: string[]; fieldErrors?: Record<string, string[]> };
    };
    if (data.details?.fieldErrors) {
      const first = Object.values(data.details.fieldErrors).flat()[0];
      if (first) return first;
    }
    if (data.details?.formErrors?.[0]) return data.details.formErrors[0];
    if (data.error) return data.error;
  } catch {
    /* ignore */
  }
  return `Request failed (${res.status})`;
}

export type PercentileKey = "p3" | "p15" | "p50" | "p85" | "p97";

export type ChartPoint = {
  x: number;
  y: number | null;
  visitId?: string;
  visitDate?: string;
  label?: string;
  /** Indicator Z-score at this visit (for color coding). */
  zScore?: number | null;
  /** Traffic-light severity derived from Z-score or visit status. */
  severityColor?: "green" | "yellow" | "orange" | "red";
};

export type PercentileCurve = {
  percentile: PercentileKey;
  points: ChartPoint[];
};

export type ChartSeries = {
  indicator: string;
  unit: string;
  xLabel: string;
  yLabel: string;
  patientPoints: ChartPoint[];
  curves: PercentileCurve[];
  referenceSource: string;
  referenceVersion: string;
};

export type ChartPayload = {
  patientId: string;
  name: string;
  sex: "MALE" | "FEMALE";
  dateOfBirth: string;
  charts: {
    WFA: ChartSeries;
    HFA: ChartSeries;
    BMI: ChartSeries;
    WFH: ChartSeries;
    HC: ChartSeries;
    velocity: ChartSeries;
  };
};

