    font-family: var(--font-body), ui-sans-serif, system-ui, sans-serif;
    background-image:
      radial-gradient(1100px 520px at 8% -12%, var(--surface-glow), transparent 55%),
      radial-gradient(900px 480px at 100% 0%, var(--surface-mist), transparent 50%),
      linear-gradient(180deg, color-mix(in oklab, var(--background) 92%, var(--primary)) 0%, var(--background) 42%, var(--background) 100%);
    background-attachment: fixed;
    min-height: 100vh;
  }

  h1,
  h2,
  h3,
  .font-display {
    font-family: var(--font-display-family), ui-serif, Georgia, serif;
    letter-spacing: -0.01em;
  }

  a {
    @apply text-inherit no-underline;
  }
}

@layer utilities {
  .container-page {
    @apply mx-auto w-full max-w-6xl px-4 sm:px-6 lg:px-8;
  }

  .section-pad {
    @apply py-16 sm:py-20 lg:py-24;
  }

  .font-telugu {
    font-family: var(--font-telugu), var(--font-body), ui-sans-serif, sans-serif;
  }

  .font-telugu h1,
  .font-telugu h2,
  .font-telugu h3,
  .font-telugu .font-display {
    font-family: var(--font-telugu), var(--font-display-family), ui-sans-serif, sans-serif;
  }
}

@keyframes learn-rise {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes learn-spine {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}

.learn-rise {
  animation: learn-rise 0.45s ease both;
}

.learn-step {
  animation: learn-rise 0.5s ease both;
}

.learn-spine {
  transform-origin: left;
  animation: learn-spine 0.7s ease 0.15s both;
}

@media (prefers-reduced-motion: reduce) {
  .learn-rise,
  .learn-step,
  .learn-spine {
    animation: none;
  }
}

@media print {
  body {
    background: white !important;
    color: black !important;
  }

  .no-print {
    display: none !important;
  }

  .print-only {
    display: block !important;
  }

  .print-break {
    break-before: page;
  }

  .recharts-wrapper,
  .chart-print-block {
    break-inside: avoid;
    page-break-inside: avoid;
  }

  .chart-print-block {
    margin-bottom: 1.25rem;
  }

  #child-health-dashboard {
    border: none;
    padding: 0;
    box-shadow: none;
  }
}

.print-only {
  display: none;
}

