"use client";

import * as React from "react";
import { useRouter } from "next/navigation";
import { calculateAge } from "@/lib/growth/age";
import { formatAge } from "@/lib/utils/format";
import { createPatientSchema } from "@/lib/validations/patient";
import { parseApiError } from "@/types/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { toast } from "@/components/ui/use-toast";

type FormState = {
  name: string;
  dateOfBirth: string;
  sex: "MALE" | "FEMALE" | "";
  birthWeightKg: string;
  weightKg: string;
  heightCm: string;
  headCircumferenceCm: string;
  mobileNumber: string;
  parentName: string;
  email: string;
  address: string;
};

const initial: FormState = {
  name: "",
  dateOfBirth: "",
  sex: "",
  birthWeightKg: "",
  weightKg: "",
  heightCm: "",
  headCircumferenceCm: "",
  mobileNumber: "",
  parentName: "",
  email: "",
  address: "",
};

function optionalNumber(value: string): number | null | undefined {
  const trimmed = value.trim();
  if (!trimmed) return null;
  const n = Number(trimmed);
  return Number.isFinite(n) ? n : Number.NaN;
}

function requiredNumber(value: string): number {
  return Number(value.trim());
}

export function RegisterForm() {
  const router = useRouter();
  const [form, setForm] = React.useState<FormState>(initial);
  const [fieldErrors, setFieldErrors] = React.useState<Record<string, string>>(
    {},
  );
  const [submitting, setSubmitting] = React.useState(false);

  const liveAge = React.useMemo(() => {
    if (!form.dateOfBirth) return null;
    try {
      return calculateAge(form.dateOfBirth);
    } catch {
      return null;
    }
  }, [form.dateOfBirth]);

  function setField<K extends keyof FormState>(key: K, value: FormState[K]) {
    setForm((prev) => ({ ...prev, [key]: value }));
    setFieldErrors((prev) => {
      const next = { ...prev };
      delete next[key];
      return next;
    });
  }

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    setFieldErrors({});

    const payload = {
      name: form.name,
      dateOfBirth: form.dateOfBirth,
      sex: form.sex || undefined,
      birthWeightKg: optionalNumber(form.birthWeightKg),
      weightKg: requiredNumber(form.weightKg),
      heightCm: requiredNumber(form.heightCm),
      headCircumferenceCm: optionalNumber(form.headCircumferenceCm),
      mobileNumber: form.mobileNumber,
      parentName: form.parentName,
      email: form.email.trim() || undefined,
      address: form.address.trim() || null,
    };

    const parsed = createPatientSchema.safeParse(payload);
    if (!parsed.success) {
      const errs: Record<string, string> = {};
      for (const issue of parsed.error.issues) {
        const key = String(issue.path[0] ?? "form");
        if (!errs[key]) errs[key] = issue.message;
      }
      setFieldErrors(errs);
      toast({
        variant: "destructive",
        title: "Please fix the form",
        description: parsed.error.issues[0]?.message ?? "Validation failed",
      });
      return;
    }

    setSubmitting(true);
    try {
      const res = await fetch("/api/patients", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(parsed.data),
      });
      if (!res.ok) throw new Error(await parseApiError(res));
      const data = (await res.json()) as { patient: { patientId: string } };
      toast({
        title: "Child registered",
        description: `Patient ID ${data.patient.patientId}`,
      });
      router.push(`/growth/patients/${encodeURIComponent(data.patient.patientId)}`);
    } catch (err) {
      toast({
        variant: "destructive",
        title: "Registration failed",
        description: err instanceof Error ? err.message : "Unknown error",
      });
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <form onSubmit={onSubmit} className="space-y-6">
      <div className="grid gap-4 sm:grid-cols-2">
        <Field
          label="Child name"
          error={fieldErrors.name}
          htmlFor="name"
        >
          <Input
            id="name"
            value={form.name}
            onChange={(e) => setField("name", e.target.value)}
            placeholder="Child full name"
            required
          />
        </Field>

        <Field label="Date of birth" error={fieldErrors.dateOfBirth} htmlFor="dob">
          <Input
            id="dob"
            type="date"
            value={form.dateOfBirth}
            max={new Date().toISOString().slice(0, 10)}
            onChange={(e) => setField("dateOfBirth", e.target.value)}
            required
          />
          {liveAge ? (
            <p className="mt-1.5 text-xs text-accent">
              Age: {formatAge(liveAge)} ({liveAge.years}y {liveAge.months}m{" "}
              {liveAge.days}d)
            </p>
          ) : null}
        </Field>

        <Field label="Sex" error={fieldErrors.sex} htmlFor="sex">
          <Select
            value={form.sex || undefined}
            onValueChange={(v) => setField("sex", v as "MALE" | "FEMALE")}
          >
            <SelectTrigger id="sex">
              <SelectValue placeholder="Select sex" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="MALE">Male</SelectItem>
              <SelectItem value="FEMALE">Female</SelectItem>
            </SelectContent>
          </Select>
        </Field>

        <Field
          label="Birth weight (kg, optional)"
          error={fieldErrors.birthWeightKg}
          htmlFor="birthWeight"
        >
          <Input
            id="birthWeight"
            type="number"
            step="0.01"
            min="0.5"
            max="8"
            value={form.birthWeightKg}
            onChange={(e) => setField("birthWeightKg", e.target.value)}
            placeholder="e.g. 2.80"
          />
        </Field>

        <Field
          label="Current weight (kg)"
          error={fieldErrors.weightKg}
          htmlFor="weight"
        >
          <Input
            id="weight"
            type="number"
            step="0.01"
            min="0.5"
            max="200"
            value={form.weightKg}
            onChange={(e) => setField("weightKg", e.target.value)}
            required
          />
        </Field>

        <Field
          label="Height / length (cm)"
          error={fieldErrors.heightCm}
          htmlFor="height"
        >
          <Input
            id="height"
            type="number"
            step="0.1"
            min="20"
            max="250"
            value={form.heightCm}
            onChange={(e) => setField("heightCm", e.target.value)}
            required
          />
        </Field>

        <Field
          label="Head circumference (cm, optional)"
          error={fieldErrors.headCircumferenceCm}
          htmlFor="hc"
        >
          <Input
            id="hc"
            type="number"
            step="0.1"
            min="20"
            max="70"
            value={form.headCircumferenceCm}
            onChange={(e) => setField("headCircumferenceCm", e.target.value)}
          />
        </Field>

        <Field
          label="Parent / guardian name"
          error={fieldErrors.parentName}
          htmlFor="parent"
        >
          <Input
            id="parent"
            value={form.parentName}
            onChange={(e) => setField("parentName", e.target.value)}
            required
          />
        </Field>

        <Field
          label="Mobile number"
          error={fieldErrors.mobileNumber}
          htmlFor="mobile"
        >
          <Input
            id="mobile"
            inputMode="numeric"
            pattern="[6-9][0-9]{9}"
            maxLength={10}
            value={form.mobileNumber}
            onChange={(e) =>
              setField("mobileNumber", e.target.value.replace(/\D/g, "").slice(0, 10))
            }
            placeholder="10-digit Indian mobile"
            required
          />
        </Field>

        <Field label="Email (optional)" error={fieldErrors.email} htmlFor="email">
          <Input
            id="email"
            type="email"
            value={form.email}
            onChange={(e) => setField("email", e.target.value)}
          />
        </Field>

        <Field
          label="Address (optional)"
          error={fieldErrors.address}
          htmlFor="address"
          className="sm:col-span-2"
        >
          <Input
            id="address"
            value={form.address}
            onChange={(e) => setField("address", e.target.value)}
          />
        </Field>
      </div>

      <Button type="submit" size="lg" disabled={submitting}>
        {submitting ? "Registering…" : "Register child"}
      </Button>
    </form>
  );
}

function Field({
  label,
  htmlFor,
  error,
  children,
  className,
}: {
  label: string;
  htmlFor: string;
  error?: string;
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <div className={className}>
      <Label htmlFor={htmlFor} className="mb-1.5 block">
        {label}
      </Label>
      {children}
      {error ? (
        <p className="mt-1 text-xs text-destructive">{error}</p>
      ) : null}
    </div>
  );
}

"use client";

import * as React from "react";
import Link from "next/link";
import { Search } from "lucide-react";
import { calculateAge } from "@/lib/growth/age";
import { formatAge, formatPatientId } from "@/lib/utils/format";
import type { ApiPatient } from "@/types/api";
import { inferSeverityColor, parseApiError } from "@/types/api";
import { StatusBadge } from "@/components/growth/status-badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent } from "@/components/ui/card";
import { toast } from "@/components/ui/use-toast";

type SearchPanelProps = {
  compact?: boolean;
  initialQuery?: string;
};

export function SearchPanel({
  compact = false,
  initialQuery = "",
}: SearchPanelProps) {
  const [q, setQ] = React.useState(initialQuery);
  const [patientId, setPatientId] = React.useState("");
  const [name, setName] = React.useState("");
  const [mobile, setMobile] = React.useState("");
  const [dob, setDob] = React.useState("");
  const [results, setResults] = React.useState<ApiPatient[]>([]);
  const [loading, setLoading] = React.useState(false);
  const [searched, setSearched] = React.useState(false);

  async function runSearch(e?: React.FormEvent) {
    e?.preventDefault();
    setLoading(true);
    setSearched(true);
    try {
      const params = new URLSearchParams();
      if (q.trim()) params.set("q", q.trim());
      if (patientId.trim()) params.set("patientId", patientId.trim());
      if (name.trim()) params.set("name", name.trim());
      if (mobile.trim()) params.set("mobile", mobile.trim());
      if (dob) params.set("dob", dob);

      if (![...params.keys()].length) {
        toast({
          variant: "destructive",
          title: "Enter a search term",
          description: "Use patient ID, name, mobile, DOB, or free text.",
        });
        setLoading(false);
        return;
      }

      const res = await fetch(`/api/patients?${params.toString()}`);
      if (!res.ok) throw new Error(await parseApiError(res));
      const data = (await res.json()) as { patients: ApiPatient[] };
      setResults(data.patients ?? []);
    } catch (err) {
      toast({
        variant: "destructive",
        title: "Search failed",
        description: err instanceof Error ? err.message : "Unknown error",
      });
      setResults([]);
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="space-y-6">
      <form onSubmit={runSearch} className="space-y-4">
        <div>
          <Label htmlFor="q" className="mb-1.5 block">
            Quick search
          </Label>
          <div className="flex gap-2">
            <Input
              id="q"
              value={q}
              onChange={(e) => setQ(e.target.value)}
              placeholder="Patient ID, name, mobile, or parent"
            />
            <Button type="submit" disabled={loading}>
              <Search className="h-4 w-4" />
              {loading ? "Searching…" : "Search"}
            </Button>
          </div>
        </div>

        {!compact ? (
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
            <div>
              <Label htmlFor="sid" className="mb-1.5 block">
                Patient ID
              </Label>
              <Input
                id="sid"
                value={patientId}
                onChange={(e) => setPatientId(e.target.value)}
              />
            </div>
            <div>
              <Label htmlFor="sname" className="mb-1.5 block">
                Name
              </Label>
              <Input
                id="sname"
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
            </div>
            <div>
              <Label htmlFor="smobile" className="mb-1.5 block">
                Mobile
              </Label>
              <Input
                id="smobile"
                value={mobile}
                onChange={(e) =>
                  setMobile(e.target.value.replace(/\D/g, "").slice(0, 10))
                }
              />
            </div>
            <div>
              <Label htmlFor="sdob" className="mb-1.5 block">
                Date of birth
              </Label>
              <Input
                id="sdob"
                type="date"
                value={dob}
                onChange={(e) => setDob(e.target.value)}
              />
            </div>
          </div>
        ) : null}
      </form>

      {searched ? (
        <div className="space-y-3">
          <p className="text-sm text-muted-foreground">
            {results.length} result{results.length === 1 ? "" : "s"}
          </p>
          {results.length === 0 ? (
            <Card>
              <CardContent className="p-6 text-sm text-muted-foreground">
                No patients matched. Try another field or register a new child.
              </CardContent>
            </Card>
          ) : (
            <ul className="space-y-3">
              {results.map((p) => {
                const age = calculateAge(p.dateOfBirth);
                const m = p.latestVisit?.measurements?.[0];
                return (
                  <li key={p.patientId}>
                    <Link
                      href={`/growth/patients/${encodeURIComponent(p.patientId)}`}
                      className="block rounded-xl border border-border bg-card p-4 transition-colors hover:border-accent/50 hover:bg-secondary/40"
                    >
                      <div className="flex flex-wrap items-start justify-between gap-3">
                        <div>
                          <p className="font-medium">{p.name}</p>
                          <p className="mt-0.5 font-mono text-xs text-muted-foreground">
                            {formatPatientId(p.patientId)}
                          </p>
                          <p className="mt-2 text-sm text-muted-foreground">
                            {formatAge(age)} · {p.sex === "MALE" ? "Male" : "Female"} ·{" "}
                            {p.mobileNumber}
                          </p>
                        </div>
                        <StatusBadge
                          label={m?.nutritionalStatus ?? "No visit"}
                          color={
                            m
                              ? inferSeverityColor(
                                  m.nutritionalStatus,
                                  m.clinicalFlags,
                                )
                              : "yellow"
                          }
                        />
                      </div>
                    </Link>
                  </li>
                );
              })}
            </ul>
          )}
        </div>
      ) : null}
    </div>
  );
}

import type { SeverityColor } from "@/lib/growth/types";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils/cn";

const variantMap = {
  green: "success",
  yellow: "warning",
  orange: "caution",
  red: "danger",
} as const;

type StatusBadgeProps = {
  label: string;
  color?: SeverityColor | null;
  className?: string;
};

export function StatusBadge({
  label,
  color = "green",
  className,
}: StatusBadgeProps) {
  const variant = variantMap[color ?? "green"];
  return (
    <Badge variant={variant} className={cn("capitalize", className)}>
      {label}
    </Badge>
  );
}

"use client";

import * as React from "react";
import QRCode from "qrcode";
import { calculateAge } from "@/lib/growth/age";
import {
  formatAge,
  formatMeasure,
  formatPatientId,
} from "@/lib/utils/format";
import type { ApiPatient } from "@/types/api";
import { inferSeverityColor } from "@/types/api";
import { StatusBadge } from "@/components/growth/status-badge";
import { Card, CardContent } from "@/components/ui/card";

type PatientSummaryProps = {
  patient: ApiPatient;
  showQr?: boolean;
};

export function PatientSummary({
  patient,
  showQr = true,
}: PatientSummaryProps) {
  const [qrDataUrl, setQrDataUrl] = React.useState<string | null>(null);
  const age = calculateAge(patient.dateOfBirth);
  const latest = patient.latestVisit;
  const measurement = latest?.measurements?.[0];
  const color = inferSeverityColor(
    measurement?.nutritionalStatus,
    measurement?.clinicalFlags,
  );

  React.useEffect(() => {
    if (!showQr) return;
    let cancelled = false;
    void QRCode.toDataURL(patient.patientId, {
      width: 160,
      margin: 1,
      color: { dark: "#0B4F6C", light: "#FFFFFF" },
    }).then((url) => {
      if (!cancelled) setQrDataUrl(url);
    });
    return () => {
      cancelled = true;
    };
  }, [patient.patientId, showQr]);

  return (
    <Card>
      <CardContent className="grid gap-6 p-6 md:grid-cols-[1fr_auto]">
        <div className="space-y-4">
          <div>
            <p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
              Patient ID
            </p>
            <p className="mt-1 font-mono text-lg font-semibold tracking-tight">
              {formatPatientId(patient.patientId)}
            </p>
          </div>

          <div className="grid gap-3 sm:grid-cols-2">
            <SummaryItem label="Name" value={patient.name} />
            <SummaryItem
              label="Sex"
              value={patient.sex === "MALE" ? "Male" : "Female"}
            />
            <SummaryItem label="Age" value={formatAge(age)} />
            <SummaryItem
              label="Date of birth"
              value={new Date(patient.dateOfBirth).toLocaleDateString("en-IN")}
            />
            <SummaryItem label="Parent" value={patient.parentName} />
            <SummaryItem label="Mobile" value={patient.mobileNumber} />
            <SummaryItem
              label="Last visit"
              value={
                latest
                  ? new Date(latest.visitDate).toLocaleDateString("en-IN")
                  : "—"
              }
            />
            <SummaryItem
              label="Visits"
              value={String(patient.visitCount ?? "—")}
            />
          </div>

          <div className="flex flex-wrap items-center gap-2">
            <span className="text-sm text-muted-foreground">Nutrition</span>
            <StatusBadge
              label={measurement?.nutritionalStatus ?? "No assessment"}
              color={measurement ? color : "yellow"}
            />
          </div>

          {latest ? (
            <div className="grid grid-cols-2 gap-3 rounded-lg bg-secondary/50 p-3 text-sm sm:grid-cols-4">
              <Metric
                label="Weight"
                value={formatMeasure(latest.weightKg, 2, "kg")}
              />
              <Metric
                label="Height"
                value={formatMeasure(latest.heightCm, 1, "cm")}
              />
              <Metric label="BMI" value={formatMeasure(latest.bmi, 1)} />
              <Metric
                label="HC"
                value={formatMeasure(latest.headCircumferenceCm, 1, "cm")}
              />
            </div>
          ) : null}
        </div>

        {showQr ? (
          <div className="flex flex-col items-center justify-center gap-2 rounded-xl border border-border bg-secondary/30 p-4">
            {qrDataUrl ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img
                src={qrDataUrl}
                alt={`QR code for ${patient.patientId}`}
                className="h-36 w-36 rounded-md bg-white p-1"
              />
            ) : (
              <div className="h-36 w-36 animate-pulse rounded-md bg-muted" />
            )}
            <p className="text-center text-xs text-muted-foreground">
              Scan to retrieve ID
            </p>
          </div>
        ) : null}
      </CardContent>
    </Card>
  );
}

function SummaryItem({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <p className="text-xs text-muted-foreground">{label}</p>
      <p className="mt-0.5 text-sm font-medium">{value}</p>
    </div>
  );
}

function Metric({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <p className="text-xs text-muted-foreground">{label}</p>
      <p className="font-medium">{value}</p>
    </div>
  );
}

import Link from "next/link";
import { ExternalLink, Printer } from "lucide-react";
import { StatusBadge } from "@/components/growth/status-badge";
import { ConditionAdvicePanel } from "@/components/nutrition/condition-advice-panel";
import { DoseResultsList } from "@/components/dosage/dose-results-list";
import { ModuleStatusBoard } from "@/components/dashboard/module-status-board";
import { ScreeningFollowUp } from "@/components/screening/screening-follow-up";
import { Button } from "@/components/ui/button";
import { CLINIC_NAME, DOCTOR_NAME, VACCINATION_FORM_URL } from "@/lib/constants";
import { formatVisitDate } from "@/lib/dashboard/modules";
import type { ChildHealthDashboard } from "@/lib/dashboard/types";
import type { SeverityColor } from "@/lib/growth/types";

type ChildHealthDashboardViewProps = {
  data: ChildHealthDashboard;
  onPrint: () => void;
  onNewRequest: () => void;
};

export function ChildHealthDashboardView({
  data,
  onPrint,
  onNewRequest,
}: ChildHealthDashboardViewProps) {
  const { nutrition, screening, includeNutrition, includeDevelopment } = data;
  const growthColor = growthSeverity(nutrition.growthLabel);
  const devColor =
    screening?.verdict === "NORMAL_DEVELOPMENT" ? "green" : "orange";

  return (
    <article id="child-health-dashboard" className="space-y-8">
      <ModuleStatusBoard
        childName={data.childName}
        ageLabel={nutrition.ageLabel}
        modules={data.modules}
      />

      <header className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
        <div>
          <p className="text-xs font-semibold uppercase tracking-wider text-accent">
            Child health dashboard
          </p>
          <h2 className="mt-1 font-display text-3xl font-semibold">{data.childName}</h2>
          <p className="mt-1 text-sm text-muted-foreground">
            {nutrition.ageLabel} · {data.sexLabel} · {nutrition.bandLabel} ·{" "}
            {data.weightKg} kg
          </p>
          <p className="mt-2 text-sm text-muted-foreground">
            {DOCTOR_NAME} · {CLINIC_NAME}
          </p>
          <p className="text-xs text-muted-foreground">Requested {data.generatedAt}</p>
        </div>
        <div className="no-print flex flex-wrap gap-2">
          <Button type="button" variant="outline" onClick={onPrint}>
            <Printer className="h-4 w-4" />
            Print dashboard
          </Button>
          <Button type="button" variant="secondary" onClick={onNewRequest}>
            New request
          </Button>
        </div>
      </header>

      <div className="flex flex-wrap gap-2">
        <StatusBadge label={nutrition.growthLabel} color={growthColor} />
        {screening ? (
          <>
            <StatusBadge label={screening.verdictLabel} color={devColor} />
            {screening.adhd.requireAssessment ? (
              <StatusBadge
                label={
                  screening.lang === "te"
                    ? "ADHD కోసం అంచనా అవసరం"
                    : "Require assessment for ADHD"
                }
                color="orange"
              />
            ) : null}
            {screening.autism.requireAssessment ? (
              <StatusBadge
                label={
                  screening.lang === "te"
                    ? "ఆటిజం కోసం అంచనా అవసరం"
                    : "Require assessment for autism"
                }
                color="orange"
              />
            ) : null}
          </>
        ) : null}
      </div>

      <section id="dash-growth" className="scroll-mt-20 space-y-3">
        <h3 className="font-display text-2xl font-semibold">Growth</h3>
        <p className="text-sm text-muted-foreground">{nutrition.growthDetail}</p>
        <p className="text-sm text-muted-foreground">
          Weight {nutrition.weightPercentExpected ?? "—"}% of expected (
          {nutrition.expectedWeightKg} kg) · Height{" "}
          {nutrition.heightPercentExpected ?? "—"}% of expected (
          {nutrition.expectedHeightCm} cm)
          {nutrition.bmi != null ? ` · BMI ${nutrition.bmi}` : ""}
        </p>
        <Button asChild variant="outline" size="sm" className="no-print">
          <Link href="/growth">Confirm on WHO/IAP charts</Link>
        </Button>
      </section>

      {includeNutrition ? (
      <section id="dash-nutrition" className="scroll-mt-20 space-y-3">
        <h3 className="font-display text-2xl font-semibold">Nutrition</h3>
        <div className="grid gap-3 sm:grid-cols-2">
          <p className="rounded-xl border border-border p-4 text-sm">
            <span className="block text-xs font-semibold uppercase tracking-wider text-muted-foreground">
              Energy
            </span>
            <span className="font-display text-2xl font-semibold">
              {nutrition.estimatedKcal} kcal
            </span>
            <span className="mt-1 block text-muted-foreground">
              Recommended ~{nutrition.recommendedKcal} kcal/day
            </span>
          </p>
          <p className="rounded-xl border border-border p-4 text-sm">
            <span className="block text-xs font-semibold uppercase tracking-wider text-muted-foreground">
              Protein
            </span>
            <span className="font-display text-2xl font-semibold">
              {nutrition.estimatedProteinG} g
            </span>
            <span className="mt-1 block text-muted-foreground">
              Recommended ~{nutrition.recommendedProteinG} g/day
            </span>
          </p>
        </div>
        {nutrition.gaps.length > 0 ? (
          <ul className="space-y-2">
            {nutrition.gaps.map((gap) => (
              <li key={gap.id} className="border-l-2 border-accent pl-4">
                <p className="font-medium">{gap.title}</p>
                <p className="text-sm text-muted-foreground">{gap.detail}</p>
              </li>
            ))}
          </ul>
        ) : (
          <p className="text-sm text-muted-foreground">No major diet gaps flagged.</p>
        )}
        <ul className="space-y-2 text-sm text-muted-foreground">
          {nutrition.feedingTips.slice(0, 3).map((tip) => (
            <li key={tip} className="flex gap-2">
              <span className="mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full bg-accent" />
              {tip}
            </li>
          ))}
        </ul>
        <div className="grid gap-4 lg:grid-cols-2">
          <div>
            <p className="font-medium">Vegetarian ideas</p>
            <ul className="mt-2 space-y-1 text-sm text-muted-foreground">
              {nutrition.vegMeals.map((m) => (
                <li key={m}>— {m}</li>
              ))}
            </ul>
          </div>
          <div>
            <p className="font-medium">Non-vegetarian ideas</p>
            <ul className="mt-2 space-y-1 text-sm text-muted-foreground">
              {nutrition.nonVegMeals.map((m) => (
                <li key={m}>— {m}</li>
              ))}
            </ul>
          </div>
        </div>
      </section>
      ) : null}

      {includeDevelopment && screening ? (
      <section
        id="dash-development"
        className={`scroll-mt-20 space-y-3${screening.lang === "te" ? " font-telugu" : ""}`}
        lang={screening.lang === "te" ? "te" : "en"}
      >
        <h3 className="font-display text-2xl font-semibold">
          {screening.lang === "te" ? "వికాసం" : "Development"}
        </h3>
        <p className="text-sm text-muted-foreground">{screening.verdictLabel}</p>
        <div className="grid gap-3 md:grid-cols-2">
          {screening.domainResults.map((domain) => (
            <div key={domain.domain} className="rounded-xl border border-border p-4">
              <div className="flex items-center justify-between gap-2">
                <p className="font-medium">{domain.label}</p>
                <StatusBadge
                  label={
                    domain.status === "typical"
                      ? screening.lang === "te"
                        ? "సాధారణం"
                        : "Typical"
                      : screening.lang === "te"
                        ? "ఎరుపు జెండాలు"
                        : "Red flags"
                  }
                  color={domain.status === "typical" ? "green" : "red"}
                />
              </div>
              {domain.status === "red_flag" ? (
                <ul className="mt-2 space-y-1 text-sm text-muted-foreground">
                  {[...domain.redFlags, ...domain.missed].map((line) => (
                    <li key={line}>— {line}</li>
                  ))}
                </ul>
              ) : null}
            </div>
          ))}
        </div>
        {screening.adhd.applicable ? (
          <p className="text-sm text-muted-foreground">
            {screening.lang === "te" ? "ADHD స్క్రీన్" : "ADHD screen"}{" "}
            {screening.adhd.score}/{screening.adhd.total}
            {screening.adhd.requireAssessment
              ? screening.lang === "te"
                ? " — ADHD కోసం అంచనా అవసరం."
                : " — require assessment for ADHD."
              : screening.lang === "te"
                ? " — పరిమితి కంటే తక్కువ."
                : " — below threshold."}
          </p>
        ) : null}
        {screening.autism.applicable ? (
          <p className="text-sm text-muted-foreground">
            {screening.lang === "te" ? "ఆటిజం స్క్రీన్" : "Autism screen"}{" "}
            {screening.autism.score}/{screening.autism.total}
            {screening.autism.requireAssessment
              ? screening.lang === "te"
                ? " — ఆటిజం కోసం అంచనా అవసరం."
                : " — require assessment for autism."
              : screening.lang === "te"
                ? " — పరిమితి కంటే తక్కువ."
                : " — below threshold."}
          </p>
        ) : null}

        <ScreeningFollowUp result={screening} />
      </section>
      ) : null}

      <section id="dash-vaccination" className="scroll-mt-20 space-y-3">
        <h3 className="font-display text-2xl font-semibold">Vaccination</h3>
        <p className="text-sm text-muted-foreground">
          Enrol for a personalised schedule PDF and automatic due-date email
          reminders.
        </p>
        <Button asChild className="no-print">
          <a href={VACCINATION_FORM_URL} target="_blank" rel="noopener noreferrer">
            Get vaccination PDF & reminders
            <ExternalLink className="h-4 w-4" />
          </a>
        </Button>
      </section>

      <section id="dash-dosage" className="scroll-mt-20 space-y-3">
        <h3 className="font-display text-2xl font-semibold">Common drugs</h3>
        <p className="text-sm text-muted-foreground">
          ml by common bottle strengths for {data.weightKg} kg. Confirm the label
          before giving. Not a prescription.
        </p>
        <DoseResultsList results={data.doses} />
        <Button asChild variant="outline" size="sm" className="no-print">
          <Link href="/dosage">Open common drugs guide</Link>
        </Button>
      </section>

      <section id="dash-checks" className="scroll-mt-20 space-y-3">
        <h3 className="font-display text-2xl font-semibold">Screens & follow-up</h3>
        <dl className="grid gap-3 sm:grid-cols-2">
          <CheckItem label="Vision" value={screenLabel(data.checks.vision)} />
          <CheckItem label="Hearing" value={screenLabel(data.checks.hearing)} />
          <CheckItem
            label="Dental"
            value={
              data.checks.dental === "ok"
                ? "OK"
                : data.checks.dental === "due"
                  ? "Due"
                  : "Not screened"
            }
          />
          <CheckItem
            label="Labs"
            value={
              data.checks.labs === "done"
                ? "Done"
                : data.checks.labs === "pending"
                  ? "Pending"
                  : "—"
            }
          />
          <CheckItem
            label="Vaccines due"
            value={data.checks.vaccinesDue > 0 ? String(data.checks.vaccinesDue) : "None noted"}
          />
          <CheckItem
            label="Next visit"
            value={formatVisitDate(data.checks.nextVisit) || "Not set"}
          />
        </dl>
      </section>

      {data.illnesses.length > 0 ? (
        <div id="dash-illness" className="scroll-mt-20">
          <ConditionAdvicePanel highlight={data.illnesses} />
        </div>
      ) : (
        <section id="dash-illness" className="scroll-mt-20 space-y-2">
          <h3 className="font-display text-2xl font-semibold">Illness feeding</h3>
          <p className="text-sm text-muted-foreground">
            No current illness was marked. Open Nutrition for English/Telugu advice
            on constipation, anaemia, diarrhoea, fever, cold & cough, and
            malnutrition.
          </p>
          <Button asChild variant="outline" size="sm" className="no-print">
            <Link href="/nutrition">Illness feeding advice</Link>
          </Button>
        </section>
      )}

      <p className="text-xs text-muted-foreground">
        Parent education dashboard — not a diagnosis. Review with {DOCTOR_NAME} at{" "}
        {CLINIC_NAME}.
      </p>
    </article>
  );
}

function CheckItem({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-xl border border-border px-4 py-3">
      <dt className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
        {label}
      </dt>
      <dd className="mt-1 font-medium">{value}</dd>
    </div>
  );
}

function screenLabel(status: "ok" | "not_screened" | "concern"): string {
  if (status === "ok") return "OK";
  if (status === "concern") return "Concern";
  return "Not screened";
}

function growthSeverity(label: string): SeverityColor {
  if (label.startsWith("Possible severe") || label.startsWith("Low BMI")) return "red";
  if (label.includes("moderate") || label.includes("overweight")) return "orange";
  if (label.includes("mild")) return "yellow";
  return "green";
}

