export function isAgeBandId(value: string | null): value is AgeBandId {
  return AGE_BANDS.some((band) => band.id === value);
}

export function topicsForBand(bandId: AgeBandId): LearnTopic[] {
  const band = AGE_BANDS.find((b) => b.id === bandId);
  if (!band) return [];
  return band.topics
    .map((id) => LEARN_TOPICS.find((t) => t.id === id))
    .filter((t): t is LearnTopic => Boolean(t));
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/** Merge Tailwind classes with clsx conditionals. */
export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

import type { AgeBreakdown } from "@/lib/growth/types";

/**
 * Format calendar age for display, e.g. "2y 3m 5d" or "11m 12d".
 */
export function formatAge(
  age: Pick<AgeBreakdown, "years" | "months" | "days"> | null | undefined,
  options?: { includeDays?: boolean }
): string {
  if (!age) return "—";
  const includeDays = options?.includeDays !== false;
  const parts: string[] = [];
  if (age.years > 0) parts.push(`${age.years}y`);
  if (age.months > 0 || age.years > 0) parts.push(`${age.months}m`);
  if (includeDays) parts.push(`${age.days}d`);
  if (parts.length === 0) return includeDays ? "0d" : "0m";
  return parts.join(" ");
}

/**
 * Format patient ID for display (keeps full immutable ID; soft wraps via
 * zero-width space after the timestamp segment when present).
 * Expected pattern: ARJYYYYMMDDHHmm-NNN
 */
export function formatPatientId(patientId: string | null | undefined): string {
  if (!patientId) return "—";
  const trimmed = patientId.trim();
  // Insert a thin visual break before the sequence suffix when hyphenated
  const m = /^([A-Z]{2,4}\d{12})-(\d+)$/i.exec(trimmed);
  if (m) return `${m[1]}-${m[2]}`;
  return trimmed;
}

/** Round a number for clinical display (default 2 dp). */
export function formatMeasure(
  value: number | null | undefined,
  digits = 2,
  unit?: string
): string {
  if (value == null || !Number.isFinite(value)) return "—";
  const n = value.toFixed(digits);
  return unit ? `${n} ${unit}` : n;
}

/** Format Z-score with sign, e.g. "+0.42" / "−1.80". */
export function formatZScore(
  z: number | null | undefined,
  digits = 2
): string {
  if (z == null || !Number.isFinite(z)) return "—";
  const abs = Math.abs(z).toFixed(digits);
  if (z > 0) return `+${abs}`;
  if (z < 0) return `−${abs}`;
  return Number(0).toFixed(digits);
}

/** Format percentile 0–100. */
export function formatPercentile(
  p: number | null | undefined,
  digits = 1
): string {
  if (p == null || !Number.isFinite(p)) return "—";
  return `${p.toFixed(digits)}%`;
}

import { z } from "zod";

const todayStart = () => {
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  return d;
};

const dateNotFuture = z
  .string()
  .or(z.date())
  .transform((v) => (v instanceof Date ? v : new Date(v)))
  .refine((d) => !Number.isNaN(d.getTime()), { message: "Invalid date" })
  .refine((d) => d <= todayStart(), {
    message: "Date of birth cannot be in the future",
  });

const indianMobile = z
  .string()
  .trim()
  .regex(/^[6-9]\d{9}$/, "Mobile number must be a valid 10-digit Indian number");

const optionalEmail = z
  .preprocess(
    (v) => (v === "" || v === null ? undefined : v),
    z.string().trim().email("Invalid email").optional(),
  );

/** Shared anthropometric bounds used at registration and visits. */
export const measurementBounds = {
  weightKg: z
    .number({ invalid_type_error: "Weight is required" })
    .min(0.5, "Weight must be at least 0.5 kg")
    .max(200, "Weight must be at most 200 kg"),
  heightCm: z
    .number({ invalid_type_error: "Height is required" })
    .min(20, "Height must be at least 20 cm")
    .max(250, "Height must be at most 250 cm"),
  headCircumferenceCm: z
    .number()
    .min(20, "Head circumference must be at least 20 cm")
    .max(70, "Head circumference must be at most 70 cm")
    .optional()
    .nullable(),
  birthWeightKg: z
    .number()
    .min(0.5, "Birth weight must be at least 0.5 kg")
    .max(8, "Birth weight must be at most 8 kg")
    .optional()
    .nullable(),
};

function assertPlausibleMeasurements(data: {
  weightKg: number;
  heightCm: number;
  headCircumferenceCm?: number | null;
  birthWeightKg?: number | null;
  dateOfBirth?: Date;
}) {
  const heightM = data.heightCm / 100;
  const bmi = data.weightKg / (heightM * heightM);

  if (bmi < 5 || bmi > 60) {
    return {
      ok: false as const,
      message:
        "Weight and height combination yields an impossible BMI (outside 5–60)",
    };
  }

  if (
    data.headCircumferenceCm != null &&
    data.headCircumferenceCm > data.heightCm
  ) {
    return {
      ok: false as const,
      message: "Head circumference cannot exceed height",
    };
  }

  if (
    data.birthWeightKg != null &&
    data.weightKg + 0.001 < data.birthWeightKg &&
    data.dateOfBirth
  ) {
    const ageDays =
      (Date.now() - data.dateOfBirth.getTime()) / (1000 * 60 * 60 * 24);
    // Allow small measurement error; flag only for older infants/children
    if (ageDays > 14) {
      return {
        ok: false as const,
        message: "Current weight cannot be less than birth weight after 2 weeks",
      };
    }
  }

  return { ok: true as const };
}

export const createPatientSchema = z
  .object({
    name: z.string().trim().min(1, "Name is required").max(120),
    dateOfBirth: dateNotFuture,
    sex: z.enum(["MALE", "FEMALE"]),
    birthWeightKg: measurementBounds.birthWeightKg,
    weightKg: measurementBounds.weightKg,
    heightCm: measurementBounds.heightCm,
    headCircumferenceCm: measurementBounds.headCircumferenceCm,
    mobileNumber: indianMobile,
    parentName: z.string().trim().min(1, "Parent name is required").max(120),
    email: optionalEmail,
    address: z.string().trim().max(500).optional().nullable(),
    notes: z.string().trim().max(2000).optional().nullable(),
    doctorAdvice: z.string().trim().max(2000).optional().nullable(),
    vaccinationStatus: z.string().trim().max(500).optional().nullable(),
    nextVisitDue: z
      .string()
      .or(z.date())
      .optional()
      .nullable()
      .transform((v) => {
        if (v == null || v === "") return null;
        return v instanceof Date ? v : new Date(v);
      })
      .refine((d) => d == null || !Number.isNaN(d.getTime()), {
        message: "Invalid next visit date",
      }),
  })
  .superRefine((data, ctx) => {
    const check = assertPlausibleMeasurements(data);
    if (!check.ok) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: check.message,
        path: ["weightKg"],
      });
    }
  });

export const updatePatientSchema = z
  .object({
    name: z.string().trim().min(1).max(120).optional(),
    dateOfBirth: dateNotFuture.optional(),
    sex: z.enum(["MALE", "FEMALE"]).optional(),
    birthWeightKg: measurementBounds.birthWeightKg,
    mobileNumber: indianMobile.optional(),
    parentName: z.string().trim().min(1).max(120).optional(),
    email: optionalEmail,
    address: z.string().trim().max(500).optional().nullable(),
    photoUrl: z.string().url().optional().nullable(),
  })
  .strict()
  .superRefine((data, ctx) => {
    if (
      data.birthWeightKg != null &&
      (data.birthWeightKg < 0.5 || data.birthWeightKg > 8)
    ) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "Birth weight must be between 0.5 and 8 kg",
        path: ["birthWeightKg"],
      });
    }
  });

export type CreatePatientInput = z.infer<typeof createPatientSchema>;
export type UpdatePatientInput = z.infer<typeof updatePatientSchema>;

