/** BMI = weight(kg) / (height(m))^2 */
export function computeBmi(weightKg: number, heightCm: number): number {
  if (!(weightKg > 0) || !(heightCm > 0)) return Number.NaN;
  const m = heightCm / 100;
  return weightKg / (m * m);
}

function buildZResult(
  indicator: GrowthIndicator,
  value: number,
  points: LmsPoint[],
  xValue: number
): ZScoreResult | null {
  const params = interpolateLms(points, xValue);
  if (!params) return null;
  const scored = computeZScoreResult(value, params);
  if (!Number.isFinite(scored.z)) return null;
  return {
    ...scored,
    indicator,
    value,
    expected: params.M,
    L: params.L,
    M: params.M,
    S: params.S,
  };
}

function monthsBetween(
  previous: PreviousVisitSnapshot,
  currentAgeMonths: number
): number {
  if (
    Number.isFinite(previous.ageMonths) &&
    Number.isFinite(currentAgeMonths)
  ) {
    const d = currentAgeMonths - previous.ageMonths;
    if (d > 0) return d;
  }
  return Number.NaN;
}

export function computeGrowthVelocity(
  previous: PreviousVisitSnapshot,
  current: { ageMonths: number; weightKg: number; heightCm: number }
): GrowthVelocity {
  const intervalMonths = monthsBetween(previous, current.ageMonths);
  const notes: string[] = [];

  if (!Number.isFinite(intervalMonths) || intervalMonths <= 0) {
    return {
      weightKgPerMonth: null,
      heightCmPerMonth: null,
      intervalMonths: 0,
      notes: ["Previous visit age must be earlier than current visit."],
    };
  }

  const weightKgPerMonth =
    (current.weightKg - previous.weightKg) / intervalMonths;
  const heightCmPerMonth =
    (current.heightCm - previous.heightCm) / intervalMonths;

  // Rough clinical heuristics (not WHO formal velocity standards)
  if (weightKgPerMonth < 0) {
    notes.push("Weight loss since previous visit.");
  } else if (weightKgPerMonth < 0.05 && current.ageMonths < 24) {
    notes.push("Low weight velocity for infancy/toddler age.");
  }

  if (heightCmPerMonth < 0) {
    notes.push("Apparent height decrease — verify measurement technique.");
  } else if (heightCmPerMonth < 0.3 && current.ageMonths < 24) {
    notes.push("Low linear growth velocity.");
  }

  if (
    previous.weightForAgeZ != null &&
    Number.isFinite(previous.weightForAgeZ) &&
    weightKgPerMonth < 0
  ) {
    notes.push("Possible growth faltering (weight).");
  }

  return {
    weightKgPerMonth,
    heightCmPerMonth,
    intervalMonths,
    notes,
  };
}

export class GrowthCalculator {
  constructor(private readonly provider: ReferenceDataProvider) {}

  async assessGrowth(input: AssessGrowthInput): Promise<GrowthAssessment> {
    const { sex, ageMonths, weightKg, heightCm } = input;
    const headCm = input.headCm ?? null;

    if (!(ageMonths >= 0) || !Number.isFinite(ageMonths)) {
      throw new Error("ageMonths must be a non-negative finite number");
    }
    if (!(weightKg > 0) || !(heightCm > 0)) {
      throw new Error("weightKg and heightCm must be positive");
    }

    const reference = selectReference(ageMonths, input.forceSource);
    const bmi = computeBmi(weightKg, heightCm);

    const load = (indicator: GrowthIndicator) =>
      Promise.resolve(
        this.provider.getLmsPoints(
          reference.source,
          reference.version,
          indicator,
          sex
        )
      );

    const [wfaPts, hfaPts, bmiPts] = await Promise.all([
      load("WEIGHT_FOR_AGE"),
      load("HEIGHT_FOR_AGE"),
      load("BMI_FOR_AGE"),
    ]);

    const weightForAge = buildZResult(
      "WEIGHT_FOR_AGE",
      weightKg,
      wfaPts,
      ageMonths
    );
    const heightForAge = buildZResult(
      "HEIGHT_FOR_AGE",
      heightCm,
      hfaPts,
      ageMonths
    );
    const bmiForAge = Number.isFinite(bmi)
      ? buildZResult("BMI_FOR_AGE", bmi, bmiPts, ageMonths)
      : null;

    let weightForHeight: ZScoreResult | null = null;
    if (supportsWeightForHeight(reference.source, ageMonths)) {
      const wfhPts = await load("WEIGHT_FOR_HEIGHT");
      weightForHeight = buildZResult(
        "WEIGHT_FOR_HEIGHT",
        weightKg,
        wfhPts,
        heightCm
      );
    }

    let headCircumferenceForAge: ZScoreResult | null = null;
    if (
      headCm != null &&
      headCm > 0 &&
      supportsHeadCircumference(reference.source, ageMonths)
    ) {
      const hcPts = await load("HEAD_CIRCUMFERENCE_FOR_AGE");
      headCircumferenceForAge = buildZResult(
        "HEAD_CIRCUMFERENCE_FOR_AGE",
        headCm,
        hcPts,
        ageMonths
      );
    }

    const classification = interpretGrowth({
      source: reference.source,
      ageMonths,
      weightForAge,
      heightForAge,
      bmiForAge,
      weightForHeight,
      headCircumferenceForAge,
    });

    const velocity = input.previousVisit
      ? computeGrowthVelocity(input.previousVisit, {
          ageMonths,
          weightKg,
          heightCm,
        })
      : null;

    return {
      reference,
      bmi,
      weightForAge,
      heightForAge,
      bmiForAge,
      weightForHeight,
      headCircumferenceForAge,
      classification,
      expectedWeightKg: weightForAge?.expected ?? null,
      expectedHeightCm: heightForAge?.expected ?? null,
      velocity,
    };
  }
}

/** Functional helper wrapping GrowthCalculator. */
export async function assessGrowth(
  provider: ReferenceDataProvider,
  input: AssessGrowthInput
): Promise<GrowthAssessment> {
  return new GrowthCalculator(provider).assessGrowth(input);
}

export type { Sex, AssessGrowthInput, GrowthAssessment, ReferenceDataProvider };

import type {
  ClinicalFlag,
  NutritionalClassification,
  ReferenceSource,
  SeverityColor,
  ZScoreResult,
} from "./types";

export interface InterpretationInput {
  source: ReferenceSource;
  ageMonths: number;
  weightForAge?: ZScoreResult | null;
  heightForAge?: ZScoreResult | null;
  bmiForAge?: ZScoreResult | null;
  /** Prefer WHZ for <5y when available; BMIZ otherwise. */
  weightForHeight?: ZScoreResult | null;
  headCircumferenceForAge?: ZScoreResult | null;
}

function severityRank(color: SeverityColor): number {
  switch (color) {
    case "green":
      return 0;
    case "yellow":
      return 1;
    case "orange":
      return 2;
    case "red":
      return 3;
  }
}

function worse(a: SeverityColor, b: SeverityColor): SeverityColor {
  return severityRank(a) >= severityRank(b) ? a : b;
}

function labelText(flag: ClinicalFlag): string {
  switch (flag) {
    case "NORMAL":
      return "Normal";
    case "UNDERWEIGHT":
      return "Underweight";
    case "SEVERE_UNDERWEIGHT":
      return "Severe Underweight";
    case "STUNTING":
      return "Stunting";
    case "SEVERE_STUNTING":
      return "Severe Stunting";
    case "WASTING":
      return "Wasting";
    case "SEVERE_WASTING":
      return "Severe Wasting";
    case "OVERWEIGHT":
      return "Overweight";
    case "OBESITY":
      return "Obesity";
    case "SEVERE_OBESITY":
      return "Severe Obesity";
    case "SHORT_STATURE":
      return "Short Stature";
    case "TALL_STATURE":
      return "Tall Stature";
    case "MICROCEPHALY":
      return "Microcephaly";
    case "MACROCEPHALY":
      return "Macrocephaly";
  }
}

const PRIMARY_ORDER: ClinicalFlag[] = [
  "SEVERE_WASTING",
  "SEVERE_UNDERWEIGHT",
  "SEVERE_STUNTING",
  "SEVERE_OBESITY",
  "WASTING",
  "UNDERWEIGHT",
  "STUNTING",
  "OBESITY",
  "SHORT_STATURE",
  "MICROCEPHALY",
  "OVERWEIGHT",
  "TALL_STATURE",
  "MACROCEPHALY",
  "NORMAL",
];

/**
 * WHO / IAP clinical interpretation with severity color coding.
 *
 * - Underweight / Severe Underweight: WAZ < −2 / < −3
 * - Stunting / Severe Stunting: HAZ < −2 / < −3 (WHO / <5y)
 * - Wasting / Severe Wasting: WHZ (preferred) or BMIZ < −2 / < −3 for <5y
 * - Overweight / Obesity / Severe Obesity: WHZ/BMIZ above +2 / +3 (WHO);
 *   IAP school-age uses BMIZ > +1 / +2 / +3 for overweight / obesity / severe
 * - Short stature / Tall stature: IAP / older HAZ < −2 / > +2
 *
 * Extreme |Z| > 3 is noted; classification uses clinical cut-offs on raw Z.
 * Callers may display clamped Z (±3) separately.
 */
export function interpretGrowth(
  input: InterpretationInput
): NutritionalClassification {
  const labels: ClinicalFlag[] = [];
  const notes: string[] = [];
  let severityColor: SeverityColor = "green";

  const waz = input.weightForAge?.z;
  const haz = input.heightForAge?.z;
  const bmiz = input.bmiForAge?.z;
  const whz = input.weightForHeight?.z;
  const hcz = input.headCircumferenceForAge?.z;

  const under5 = input.ageMonths < 60;
  const useWhoRules = input.source === "WHO" || under5;
  const wastingZ = under5 ? (whz ?? bmiz) : bmiz;

  // Weight-for-age
  if (waz != null && Number.isFinite(waz)) {
    if (waz < -3) {
      labels.push("SEVERE_UNDERWEIGHT");
      severityColor = worse(severityColor, "red");
      if (input.weightForAge?.isExtreme) {
        notes.push("WAZ extreme (< −3); display Z may be clamped to ±3.");
      }
    } else if (waz < -2) {
      labels.push("UNDERWEIGHT");
      severityColor = worse(severityColor, "orange");
    }
  }

  // Length / height-for-age
  if (haz != null && Number.isFinite(haz)) {
    if (useWhoRules) {
      if (haz < -3) {
        labels.push("SEVERE_STUNTING");
        severityColor = worse(severityColor, "red");
      } else if (haz < -2) {
        labels.push("STUNTING");
        severityColor = worse(severityColor, "orange");
      }
    } else {
      if (haz < -2) {
        labels.push("SHORT_STATURE");
        severityColor = worse(severityColor, haz < -3 ? "red" : "orange");
        if (haz < -3) notes.push("HAZ < −3: severe short stature.");
      } else if (haz > 2) {
        labels.push("TALL_STATURE");
        severityColor = worse(severityColor, haz > 3 ? "orange" : "yellow");
      }
    }
  }

  // Wasting / adiposity
  if (wastingZ != null && Number.isFinite(wastingZ)) {
    if (wastingZ < -3) {
      labels.push("SEVERE_WASTING");
      severityColor = worse(severityColor, "red");
    } else if (wastingZ < -2) {
      labels.push("WASTING");
      severityColor = worse(severityColor, "orange");
    }

    if (useWhoRules) {
      // WHO: >+2 overweight, >+3 obesity
      if (wastingZ > 3) {
        labels.push("OBESITY");
        severityColor = worse(severityColor, "orange");
      } else if (wastingZ > 2) {
        labels.push("OVERWEIGHT");
        severityColor = worse(severityColor, "yellow");
      }
    } else {
      // IAP older children: BMIZ >+1 overweight, >+2 obesity, >+3 severe
      if (wastingZ > 3) {
        labels.push("SEVERE_OBESITY");
        severityColor = worse(severityColor, "red");
      } else if (wastingZ > 2) {
        labels.push("OBESITY");
        severityColor = worse(severityColor, "orange");
      } else if (wastingZ > 1) {
        labels.push("OVERWEIGHT");
        severityColor = worse(severityColor, "yellow");
      }
    }
  }

  // Head circumference
  if (hcz != null && Number.isFinite(hcz)) {
    if (hcz < -2) {
      labels.push("MICROCEPHALY");
      severityColor = worse(severityColor, hcz < -3 ? "red" : "orange");
    } else if (hcz > 2) {
      labels.push("MACROCEPHALY");
      severityColor = worse(severityColor, hcz > 3 ? "orange" : "yellow");
    }
  }

  const unique: ClinicalFlag[] = [];
  for (const l of labels) {
    if (!unique.includes(l)) unique.push(l);
  }

  if (unique.length === 0) {
    unique.push("NORMAL");
    severityColor = "green";
  }

  let primary: ClinicalFlag = "NORMAL";
  for (const candidate of PRIMARY_ORDER) {
    if (unique.includes(candidate)) {
      primary = candidate;
      break;
    }
  }

  return {
    labels: unique,
    primaryStatus: labelText(primary),
    severityColor,
    notes: notes.length ? notes : undefined,
  };
}

/** Sex as used by growth references (aligned with Prisma Sex enum). */
export type Sex = "MALE" | "FEMALE";

/** Anthropometric indicator for LMS lookup. */
export type GrowthIndicator =
  | "WEIGHT_FOR_AGE"
  | "HEIGHT_FOR_AGE"
  | "BMI_FOR_AGE"
  | "WEIGHT_FOR_HEIGHT"
  | "HEAD_CIRCUMFERENCE_FOR_AGE";

/**
 * Reference chart family.
 * CDC is intentionally excluded — this app uses WHO (<5y) and IAP (≥5y) only.
 */
export type ReferenceSource = "WHO" | "IAP";

/** Published dataset versions used by this engine. */
export type ReferenceVersion = "WHO-2006" | "IAP-2015";

/** LMS Box-Cox parameters for a single x-value (age months or height cm). */
export interface LmsParams {
  L: number;
  M: number;
  S: number;
}

/** One LMS data point on a reference curve. */
export interface LmsPoint extends LmsParams {
  /** Age in months, or height in cm when indicator is WEIGHT_FOR_HEIGHT. */
  xValue: number;
  /** Derived / published chart percentiles (measurement units). */
  p3?: number;
  p15?: number;
  p50?: number;
  p85?: number;
  p97?: number;
}

export interface ZScoreResult {
  /** Raw LMS Z-score (unclamped). */
  z: number;
  /** Z clamped to ±3 for classification display notes. */
  zClamped: number;
  /** Percentile 0–100 derived from raw Z via normal CDF. */
  percentile: number;
  /** Whether raw |Z| exceeded 3. */
  isExtreme: boolean;
  indicator: GrowthIndicator;
  /** Measurement used (kg, cm, or kg/m²). */
  value: number;
  /** Expected median (M) at this age/height. */
  expected: number;
  L: number;
  M: number;
  S: number;
}

export type SeverityColor = "green" | "yellow" | "orange" | "red";

export type ClinicalFlag =
  | "NORMAL"
  | "UNDERWEIGHT"
