import { promises as fs } from "node:fs";
import path from "node:path";
import type {
  GrowthIndicator,
  GrowthReferenceManifest,
  LmsFilePayload,
  LmsPoint,
  ReferenceDataProvider,
  ReferenceSource,
  Sex,
} from "./types";

type PrismaLmsClient = {
  growthReferenceVersion: {
    findUnique: (args: {
      where: { source_version: { source: ReferenceSource; version: string } };
      include?: { lmsPoints?: boolean | { where: Record<string, unknown> } };
    }) => Promise<{
      id: string;
      lmsPoints?: Array<{
        indicator: GrowthIndicator;
        sex: Sex;
        xValue: number;
        L: number;
        M: number;
        S: number;
        p3: number | null;
        p15: number | null;
        p50: number | null;
        p85: number | null;
        p97: number | null;
      }>;
    } | null>;
  };
  lmsDataPoint: {
    findMany: (args: {
      where: {
        versionId: string;
        indicator: GrowthIndicator;
        sex: Sex;
      };
      orderBy: { xValue: "asc" };
    }) => Promise<
      Array<{
        xValue: number;
        L: number;
        M: number;
        S: number;
        p3: number | null;
        p15: number | null;
        p50: number | null;
        p85: number | null;
        p97: number | null;
      }>
    >;
  };
};

export interface ReferenceLoaderOptions {
  /** Absolute or cwd-relative path to data/growth-references */
  dataRoot?: string;
  /** Optional Prisma client for DB-backed LMS points. */
  prisma?: PrismaLmsClient | null;
  /** Prefer DB when both DB and files are available. Default false (files first). */
  preferDatabase?: boolean;
}

const FOLDER_BY_VERSION: Record<string, string> = {
  "WHO-2006": "who-2006",
  "IAP-2015": "iap-2015",
};

function defaultDataRoot(): string {
  return path.join(process.cwd(), "data", "growth-references");
}

function cacheKey(
  source: ReferenceSource,
  version: string,
  indicator: GrowthIndicator,
  sex: Sex
): string {
  return `${source}|${version}|${indicator}|${sex}`;
}

/**
 * Loads versioned LMS JSON from `data/growth-references/{folder}/`
 * (manifest.json + indicator files). Results are cached in memory.
 * Optionally falls back to / prefers Prisma `GrowthReferenceVersion` + `LmsDataPoint`.
 */
export class FileReferenceLoader implements ReferenceDataProvider {
  private readonly dataRoot: string;
  private readonly prisma: PrismaLmsClient | null;
  private readonly preferDatabase: boolean;
  private readonly pointCache = new Map<string, LmsPoint[]>();
  private readonly manifestCache = new Map<string, GrowthReferenceManifest>();

  constructor(options: ReferenceLoaderOptions = {}) {
    this.dataRoot = options.dataRoot ?? defaultDataRoot();
    this.prisma = options.prisma ?? null;
    this.preferDatabase = options.preferDatabase ?? false;
  }

  clearCache(): void {
    this.pointCache.clear();
    this.manifestCache.clear();
  }

  async getManifest(
    source: ReferenceSource,
    version: string
  ): Promise<GrowthReferenceManifest> {
    const key = `${source}|${version}`;
    const cached = this.manifestCache.get(key);
    if (cached) return cached;

    const folder = FOLDER_BY_VERSION[version] ?? version.toLowerCase();
    const manifestPath = path.join(this.dataRoot, folder, "manifest.json");
    const raw = await fs.readFile(manifestPath, "utf8");
    const manifest = JSON.parse(raw) as GrowthReferenceManifest;
    this.manifestCache.set(key, manifest);
    return manifest;
  }

  async getLmsPoints(
    source: ReferenceSource,
    version: string,
    indicator: GrowthIndicator,
    sex: Sex
  ): Promise<LmsPoint[]> {
    const key = cacheKey(source, version, indicator, sex);
    const hit = this.pointCache.get(key);
    if (hit) return hit;

    if (this.preferDatabase && this.prisma) {
      const fromDb = await this.loadFromPrisma(source, version, indicator, sex);
      if (fromDb.length) {
        this.pointCache.set(key, fromDb);
        return fromDb;
      }
    }

    try {
      const fromFile = await this.loadFromFiles(source, version, indicator, sex);
      this.pointCache.set(key, fromFile);
      return fromFile;
    } catch (fileErr) {
      if (this.prisma) {
        const fromDb = await this.loadFromPrisma(
          source,
          version,
          indicator,
          sex
        );
        if (fromDb.length) {
          this.pointCache.set(key, fromDb);
          return fromDb;
        }
      }
      throw fileErr;
    }
  }

  private async loadFromFiles(
    source: ReferenceSource,
    version: string,
    indicator: GrowthIndicator,
    sex: Sex
  ): Promise<LmsPoint[]> {
    const manifest = await this.getManifest(source, version);
    const fileName = manifest.files[indicator];
    if (!fileName) {
      throw new Error(
        `Manifest for ${source}/${version} has no file for ${indicator}`
      );
    }

    const folder = FOLDER_BY_VERSION[version] ?? version.toLowerCase();
    const filePath = path.join(this.dataRoot, folder, fileName);
    const raw = await fs.readFile(filePath, "utf8");
    const payload = JSON.parse(raw) as LmsFilePayload | LmsFilePayload[];

    const records = Array.isArray(payload) ? payload : [payload];
    const match = records.find(
      (r) =>
        r.indicator === indicator &&
        r.sex === sex &&
        (r.source === source || !r.source) &&
        (r.version === version || !r.version)
    );

    if (!match) {
      // Some generators store one file per indicator with both sexes inside
      const both = records.flatMap((r) =>
        r.sex === sex && r.indicator === indicator ? [r] : []
      );
      if (!both.length) {
        // Try sex-keyed object format: { MALE: { points }, FEMALE: { points } }
        const asMap = JSON.parse(raw) as Record<
          string,
          { points?: LmsPoint[]; L?: never } | LmsPoint[]
        >;
        const sexBlock = asMap[sex];
        if (Array.isArray(sexBlock)) return sortPoints(sexBlock);
        if (sexBlock && Array.isArray(sexBlock.points)) {
          return sortPoints(sexBlock.points);
        }
        throw new Error(
          `No LMS points for ${source}/${version}/${indicator}/${sex} in ${fileName}`
        );
      }
      return sortPoints(both[0]!.points);
    }

    return sortPoints(match.points);
  }

  private async loadFromPrisma(
    source: ReferenceSource,
    version: string,
    indicator: GrowthIndicator,
    sex: Sex
  ): Promise<LmsPoint[]> {
    if (!this.prisma) return [];

    const ver = await this.prisma.growthReferenceVersion.findUnique({
      where: { source_version: { source, version } },
    });
    if (!ver) return [];

    const rows = await this.prisma.lmsDataPoint.findMany({
      where: { versionId: ver.id, indicator, sex },
      orderBy: { xValue: "asc" },
    });

    return rows.map((r) => ({
      xValue: r.xValue,
      L: r.L,
      M: r.M,
      S: r.S,
      p3: r.p3 ?? undefined,
      p15: r.p15 ?? undefined,
      p50: r.p50 ?? undefined,
      p85: r.p85 ?? undefined,
      p97: r.p97 ?? undefined,
    }));
  }
}

function sortPoints(points: LmsPoint[]): LmsPoint[] {
  return [...points].sort((a, b) => a.xValue - b.xValue);
}

/** Singleton helper for app code. */
let defaultLoader: FileReferenceLoader | null = null;

export function getReferenceLoader(
  options?: ReferenceLoaderOptions
): FileReferenceLoader {
  if (options) return new FileReferenceLoader(options);
  if (!defaultLoader) defaultLoader = new FileReferenceLoader();
  return defaultLoader;
}

import type { SeverityColor } from "@/lib/growth/types";

/** Print / canvas RGB for clinical severity (Green / Orange / Red). */
export const SEVERITY_RGB: Record<
  "green" | "orange" | "red" | "yellow",
  [number, number, number]
> = {
  green: [26, 122, 76],
  yellow: [201, 148, 0],
  orange: [192, 86, 0],
  red: [180, 35, 24],
};

export const SEVERITY_HEX: Record<"green" | "orange" | "red" | "yellow", string> =
  {
    green: "#1a7a4c",
    yellow: "#c99400",
    orange: "#c05600",
    red: "#b42318",
  };

/** Soft fills for chart percentile bands. */
export const ZONE_FILL = {
  green: "rgba(26, 122, 76, 0.18)",
  orange: "rgba(192, 86, 0, 0.16)",
  red: "rgba(180, 35, 24, 0.12)",
} as const;

/**
 * Map a Z-score to Green / Orange / Red for chart dots and PDF.
 * |Z| < 2 → green, 2–3 → orange, ≥ 3 → red.
 */
export function severityFromZ(z: number | null | undefined): SeverityColor {
  if (z == null || !Number.isFinite(z)) return "green";
  const a = Math.abs(z);
  if (a >= 3) return "red";
  if (a >= 2) return "orange";
  if (a >= 1) return "yellow";
  return "green";
}

/** Collapse yellow into orange when only Green/Orange/Red are desired. */
export function toTrafficLight(
  color: SeverityColor | null | undefined,
): "green" | "orange" | "red" {
  if (color === "red") return "red";
  if (color === "orange" || color === "yellow") return "orange";
  return "green";
}

export function severityFromStatus(
  status?: string | null,
  flags?: string[] | null,
): "green" | "orange" | "red" {
  const hay = `${status ?? ""} ${(flags ?? []).join(" ")}`.toUpperCase();
  if (/SEVERE|CRITICAL/.test(hay)) return "red";
  if (
    /WASTING|STUNTING|UNDERWEIGHT|OBESITY|OVERWEIGHT|MICROCEPHALY|MACROCEPHALY|SHORT|TALL/.test(
      hay,
    )
  ) {
    return "orange";
  }
  return "green";
}

import type { AgeBreakdown } from "./types";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
/** Average Gregorian month length used for fractional LMS age. */
const DAYS_PER_MONTH = 30.4375;

function toUtcDateOnly(d: Date): Date {
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
}

function parseDate(input: Date | string): Date {
  if (input instanceof Date) {
    if (Number.isNaN(input.getTime())) {
      throw new Error("Invalid date");
    }
    return input;
  }
  const parsed = new Date(input);
  if (Number.isNaN(parsed.getTime())) {
    throw new Error(`Invalid date string: ${input}`);
  }
  return parsed;
}

/**
 * Calendar age between DOB and an assessment date.
 * Never returns negative components — if onDate < dob, all zeros.
 */
export function calculateAge(
  dob: Date | string,
  onDate: Date | string = new Date()
): AgeBreakdown {
  const birth = toUtcDateOnly(parseDate(dob));
  const on = toUtcDateOnly(parseDate(onDate));

  if (on.getTime() < birth.getTime()) {
    return {
      years: 0,
      months: 0,
      days: 0,
      totalMonths: 0,
      totalDays: 0,
      ageMonthsExact: 0,
    };
  }

  let years = on.getUTCFullYear() - birth.getUTCFullYear();
  let months = on.getUTCMonth() - birth.getUTCMonth();
  let days = on.getUTCDate() - birth.getUTCDate();

  if (days < 0) {
    // Borrow days from previous month
    const prevMonth = new Date(Date.UTC(on.getUTCFullYear(), on.getUTCMonth(), 0));
    days += prevMonth.getUTCDate();
    months -= 1;
  }

  if (months < 0) {
    months += 12;
    years -= 1;
  }

  const totalDays = Math.floor((on.getTime() - birth.getTime()) / MS_PER_DAY);
  const totalMonths = years * 12 + months;
  const ageMonthsExact = totalDays / DAYS_PER_MONTH;

  return {
    years: Math.max(0, years),
    months: Math.max(0, months),
    days: Math.max(0, days),
    totalMonths: Math.max(0, totalMonths),
    totalDays: Math.max(0, totalDays),
    ageMonthsExact: Math.max(0, ageMonthsExact),
  };
}

/** Convert exact day count to fractional months for LMS lookup. */
export function daysToMonths(totalDays: number): number {
  return Math.max(0, totalDays) / DAYS_PER_MONTH;
}

export { DAYS_PER_MONTH };

import type { DashboardModuleRow, HealthChecks, ScreenStatus } from "./types";

function screenRow(
  status: ScreenStatus,
  okText = "OK",
): Pick<DashboardModuleRow, "tone" | "statusText" | "showDot"> {
  if (status === "ok") return { tone: "ok", statusText: okText, showDot: true };
  if (status === "concern")
    return { tone: "watch", statusText: "Concern", showDot: true };
  return { tone: "due", statusText: "Not screened", showDot: false };
}

export function buildModuleRows(data: {
  nutritionLabel: string;
  nutritionGaps: number;
  includeNutrition: boolean;
  includeDevelopment: boolean;
  developmentOk: boolean;
  developmentNeeds: boolean;
  adhd: boolean;
  autism: boolean;
  checks: HealthChecks;
  illnessCount: number;
}): DashboardModuleRow[] {
  const growthWatch =
    data.nutritionLabel.includes("undernutrition") ||
    data.nutritionLabel.includes("overweight") ||
    data.nutritionLabel.includes("Low BMI") ||
    data.nutritionLabel.includes("Obesity");
  const growthBad =
    data.nutritionLabel.includes("severe") || data.nutritionLabel.includes("Severe");

  let growth: Pick<DashboardModuleRow, "tone" | "statusText" | "showDot"> = {
    tone: "ok",
    statusText: "On track",
    showDot: true,
  };
  if (growthBad)
    growth = { tone: "watch", statusText: "Review now", showDot: true };
  else if (growthWatch)
    growth = { tone: "watch", statusText: "Watch", showDot: true };

  let development: Pick<DashboardModuleRow, "tone" | "statusText" | "showDot"> = {
    tone: "ok",
    statusText: "Typical",
    showDot: true,
  };
  if (!data.includeDevelopment)
    development = { tone: "empty", statusText: "Not included", showDot: false };
  else if (data.adhd || data.autism)
    development = { tone: "watch", statusText: "Assess", showDot: true };
  else if (data.developmentNeeds)
    development = { tone: "watch", statusText: "Review", showDot: true };

  const vaxDue = Math.max(0, data.checks.vaccinesDue);
  const vaccination: Pick<DashboardModuleRow, "tone" | "statusText" | "showDot"> =
    vaxDue > 0
      ? { tone: "watch", statusText: `${vaxDue} due`, showDot: true }
      : { tone: "ok", statusText: "Enrol / track", showDot: true };

  const nutrition: Pick<DashboardModuleRow, "tone" | "statusText" | "showDot"> =
    !data.includeNutrition
      ? { tone: "empty", statusText: "Not included", showDot: false }
      : data.nutritionGaps > 0
        ? {
            tone: "watch",
            statusText: `${data.nutritionGaps} gap${data.nutritionGaps === 1 ? "" : "s"}`,
            showDot: true,
          }
        : { tone: "ok", statusText: "On track", showDot: true };

  const dental =
    data.checks.dental === "ok"
      ? { tone: "ok" as const, statusText: "OK", showDot: true }
      : data.checks.dental === "due"
        ? { tone: "due" as const, statusText: "Due", showDot: false }
        : { tone: "due" as const, statusText: "Not screened", showDot: false };

  const labs =
    data.checks.labs === "done"
      ? { tone: "ok" as const, statusText: "Done", showDot: true }
      : data.checks.labs === "pending"
        ? { tone: "watch" as const, statusText: "Pending", showDot: true }
        : { tone: "empty" as const, statusText: "—", showDot: false };

  const episodes = Math.max(data.checks.illnessEpisodes, data.illnessCount);

  return [
    { id: "growth", label: "Growth", href: "#dash-growth", accent: "#34d399", ...growth },
    { id: "development", label: "Development", href: "#dash-development", accent: "#60a5fa", ...development },
    { id: "vaccination", label: "Vaccination", href: "#dash-vaccination", accent: "#fbbf24", ...vaccination },
    { id: "nutrition", label: "Nutrition", href: "#dash-nutrition", accent: "#a3e635", ...nutrition },
    { id: "vision", label: "Vision", href: "#dash-checks", accent: "#22d3ee", ...screenRow(data.checks.vision) },
    { id: "hearing", label: "Hearing", href: "#dash-checks", accent: "#c084fc", ...screenRow(data.checks.hearing) },
    { id: "dental", label: "Dental", href: "#dash-checks", accent: "#fb7185", ...dental },
    { id: "labs", label: "Labs", href: "#dash-checks", accent: "#94a3b8", ...labs },
    {
      id: "illness",
      label: "Illness history",
      href: "#dash-illness",
      accent: "#fb923c",
      tone: episodes > 0 ? "info" : "empty",
      statusText: episodes > 0 ? `${episodes} episode${episodes === 1 ? "" : "s"}` : "None noted",
      showDot: false,
    },
    {
      id: "next",
      label: "Next visit",
      href: "#dash-checks",
      accent: "#2dd4bf",
      tone: data.checks.nextVisit.trim() ? "info" : "empty",
      statusText: formatVisitDate(data.checks.nextVisit) || "Not set",
      showDot: false,
    },
    {
      id: "dosage",
      label: "Common drugs",
      href: "#dash-dosage",
      accent: "#f472b6",
      tone: "ok",
      statusText: "Ready",
      showDot: true,
    },
  ];
}

export function emptyHealthChecks(): HealthChecks {
  return {
    vision: "not_screened",
    hearing: "not_screened",
    dental: "not_screened",
    labs: "none",
    vaccinesDue: 0,
    illnessEpisodes: 0,
    nextVisit: "",
  };
}

export function formatVisitDate(iso: string): string {
  const trimmed = iso.trim();
  if (!trimmed) return "";
  const d = new Date(`${trimmed}T00:00:00`);
  if (Number.isNaN(d.getTime())) return trimmed;
  return d.toLocaleDateString("en-GB", { day: "numeric", month: "short" });
}

