export type ActivityFocus =
  | MilestoneDomain
  | "adhd"
  | "autism"
  | "general";

export type ActivityItem = {
  focus: ActivityFocus;
  title: LocalizedText;
  steps: LocalizedText[];
};

export type ActivityGroup = {
